public class RabinKarp {
    static final int BASE = 256, MOD = 101;
    public void search(String text, String pattern) {
        int n=text.length(), m=pattern.length();
        int h = (int)Math.pow(BASE, m-1) % MOD;
        int pH = 0, tH = 0;
        for (int i=0; i<m; i++) { pH=(BASE*pH+pattern.charAt(i))%MOD; tH=(BASE*tH+text.charAt(i))%MOD; }
        for (int i=0; i<=n-m; i++) {
            if (pH==tH && text.substring(i,i+m).equals(pattern)) System.out.println("Found at "+i);
            if (i<n-m) { tH=(BASE*(tH-text.charAt(i)*h)+text.charAt(i+m))%MOD; if(tH<0)tH+=MOD; }
        }
    }
}

