#include <stdio.h>
#define B 256
#define M 101
void rabinKarp(char*t, char*p) {
    int n=strlen(t), m=strlen(p), h=1, ph=0, th=0;
    for (int i=0; i<m-1; i++)h=(h*B)%M;
    for (int i=0; i<m; i++) {
        ph=(B*ph+p[i])%M;
        th=(B*th+t[i])%M;
    }
    for (int i=0; i<=n-m; i++) {
        if (ph==th) {
            int j=0;
            while (j<m&&t[i+j]==p[j])j++;
            if (j==m)printf("Found at %d\n", i);
        }
        if (i<n-m) {
            th=(B*(th-t[i]*h)+t[i+m])%M;
            if (th<0)th+=M;
        }
    }
}

