def rabin_karp(text, pat, base=256, mod=101):
    n, m = len(text), len(pat)
    if m > n:
        return []
    high = pow(base, m - 1, mod)
    ph = th = 0
    for i in range(m):
        ph = (base * ph + ord(pat[i])) % mod
        th = (base * th + ord(text[i])) % mod
    hits = []
    for i in range(n - m + 1):
        if ph == th and text[i:i+m] == pat:
            hits.append(i)
        if i < n - m:
            th = (base * (th - ord(text[i]) * high) + ord(text[i+m])) % mod
    return hits

